export type InviteMemberFormProps = {
  orgId: OrgId;
  actor: Actor;
  seatCheck: LimitCheck;
  onSubmit: (input: InviteMemberInput) => Promise<ActionResult<Invitation>>;
};

export function InviteMemberForm(
  props: InviteMemberFormProps,
): ReactElement | null {
  const { orgId, actor, seatCheck, onSubmit } = props;

  const [email, setEmail] = useState("");
  const [role, setRole] = useState<Role>("member");
  const [invalid, setInvalid] = useState<string | null>(null);

  const { submit, pending, error } = useFormAction(onSubmit, {
    onSuccess: () => setEmail(""),
  });

  // Hiding the form is not the enforcement — `inviteMemberAction` calls
  // `assertCan` for the same pair — but offering an impossible action is worse
  // than not offering it.
  if (!can(actor, "member:invite", organizationResource(orgId))) return null;

  // The quota number comes from the plan table, never from a literal.
  const limits = getPlanLimits(seatCheck.plan);
  const seatsExhausted = seatCheck.exceeded || seatCheck.remaining <= 0;

  async function handleSubmit(): Promise<void> {
    const parsed = inviteMemberSchema.safeParse({ orgId, email, role });
    if (!parsed.success) {
      setInvalid(parsed.error.issues[0]?.message ?? "Check the address");
      return;
    }
    setInvalid(null);
    await submit(parsed.data);
  }

  return (
    <div className="invite-member-form space-y-3">
      {seatsExhausted ? (
        <Alert tone="warning" title="Seat limit reached">
          The {seatCheck.plan} plan includes {formatLimit(limits.seats)} seats
          and {seatCheck.used} are in use. Upgrade to invite more teammates.
        </Alert>
      ) : null}

      <FormField name="email" label="Email" required error={invalid}>
        <Input
          name="email"
          type="email"
          value={email}
          placeholder="teammate@example.com"
          invalid={invalid !== null}
          disabled={seatsExhausted}
          onChange={setEmail}
        />
      </FormField>

      <FormField name="role" label="Role">
        <RoleSelect
          value={role}
          actor={actor}
          disabled={seatsExhausted}
          onChange={setRole}
        />
      </FormField>

      <ErrorMessage message={error?.message ?? null} />

      <Button
        type="button"
        loading={pending}
        disabled={pending || seatsExhausted || email.length === 0}
        onClick={() => void handleSubmit()}
      >
        Send invitation
      </Button>
    </div>
  );
}
/**
 * Current usage and limit checks for one organization.
 *
 * Owner D. Returns the raw counters *and* the plan ceilings side by side, so a
 * dashboard can render a meter without knowing the plan table itself.
 *
 * Must call (do not reimplement): can, assertOrgScope, getPlanLimits
 */

import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getPlanLimits } from "@/config/plan-limits";
import { requireActorFor } from "@/lib/actor";
import { can } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { orgIdSchema } from "@/schemas/common";
import { checkLimit } from "@/server/services/billing-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import { getUsage } from "@/server/services/usage-service";
import type { LimitedResource } from "@/types/billing";

export const dynamic = "force-dynamic";

type RouteContext = { params: Promise<{ orgId: string }> };

const REPORTED: readonly LimitedResource[] = [
  "seats",
  "projects",
  "storageMb",
  "webhooks",
];

export async function GET(
  request: Request,
  context: RouteContext,
): Promise<Response> {
  void request;

  try {
    // Next.js 16: route `params` is a Promise and MUST be awaited.
    const { orgId } = await context.params;
    const parsed = orgIdSchema.safeParse(orgId);
    if (!parsed.success) {
      return failure("validation_failed", "Malformed organization id.");
    }

    const actor = await requireActorFor(parsed.data);
    assertOrgScope(actor, parsed.data);

    if (!can(actor, "org:read", { kind: "organization", orgId: parsed.data })) {
      return failure("forbidden", "You cannot read this organization.");
    }

    const [{ organization }, usage] = await Promise.all([
      getOrganizationSummary(actor, parsed.data),
      getUsage(actor, parsed.data),
    ]);

    const limits = getPlanLimits(organization.plan);
    const checks = await Promise.all(
      REPORTED.map((resource) => checkLimit(parsed.data, resource, 0)),
    );

    return Response.json({ plan: organization.plan, limits, usage, checks });
  } catch (error) {
    return errorResponse(error);
  }
}
